import math

u1 = (1, 1, 0)
u2 = (1, 0, 1)
u3 = (0, 1, 1)

def dot(a, b):
    return sum(x*y for x, y in zip(a, b))

def norm(a):
    return math.sqrt(dot(a, a))

def scale(s, a):
    return tuple(s*x for x in a)

def sub(a, b):
    return tuple(x - y for x, y in zip(a, b))

e1 = scale(1/norm(u1), u1)
v2 = sub(u2, scale(dot(u2, e1), e1))
e2 = scale(1/norm(v2), v2)
v3 = sub(sub(u3, scale(dot(u3, e1), e1)), scale(dot(u3, e2), e2))
e3 = scale(1/norm(v3), v3)

for vec in (e1, e2, e3):
    for x in vec:
        print(round(x, 6))
